using Avalonia;

namespace GuiEventsLab;

// CSCI 1260 GUIs and Events Lab. Do not edit this file.
//
//   dotnet run            opens the window
//   dotnet run -- check   prints the lab check instead
//
// On GitHub there is no screen, so the check runs on its own there.
public static class Program
{
    [STAThread]
    public static void Main(string[] args)
    {
        if (LabCheck.ShouldRun(args))
        {
            LabCheck.Run();
        }
        else
        {
            BuildAvaloniaApp().StartWithClassicDesktopLifetime(args);
        }
    }

    // Avalonia configuration. The visual designer uses this method too.
    public static AppBuilder BuildAvaloniaApp()
    {
        return AppBuilder.Configure<App>()
            .UsePlatformDetect()
#if DEBUG
            .WithDeveloperTools()
#endif
            .WithInterFont()
            .LogToTrace();
    }
}
